import representations_ops_l2 as ops
def _err(P, X):
    return float(((ops.tanh_ae_forward(P, X) - X) ** 2).sum(1).mean())
def _pca(Xtr, Xte):
    mu = Xtr.mean(0); w, V = np.linalg.eigh((Xtr - mu).T @ (Xtr - mu)); v = V[:, -1:]; T = Xte - mu
    return float(((T - T @ v @ v.T) ** 2).sum(1).mean())

